use std::ffi::CStr;
use std::os::raw::c_char;

fn parse_c_str(
    p: *const c_char,
) -> Option<&'static str> {
    if p.is_null() {
        return None;
    }
    let c = CStr::from_ptr(p);
    c.to_str().ok()
}

