#[test]
fn parses_c_str() {
    let bytes = b"hello\0";
    let ptr = bytes.as_ptr() as *const std::os::raw::c_char;
    assert_eq!(parse_c_str(ptr), Some("hello"));
    assert_eq!(parse_c_str(std::ptr::null()), None);
}
